import{_ as o,l,o as e,c as A,v as t,p as n,x as i,d as E,i as s,S as p}from"./chunks/framework.InCnrqk-.js";const m=JSON.parse('{"title":"成交后分析 TCA","description":"","frontmatter":{"title":"成交后分析 TCA","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/tca.md","filePath":"quant/tca.md","lastUpdated":1789023840000}'),B={name:"quant/tca.md"};function d(h,a,c,_,P,T){const r=l("Mermaid");return e(),A("div",null,[a[1]||(a[1]=t('<h1 id="成交后分析-tca" tabindex="-1">成交后分析 TCA <a class="header-anchor" href="#成交后分析-tca" aria-label="Permalink to &quot;成交后分析 TCA&quot;">​</a></h1><div class="epigraph"><p>成交之后才知道均价、未完成量与当时市场走了多远；把这些数对照事先选定的基准拆开，执行过程才从轶事变成可改的参数。</p><footer>—— 据 Perold 实施缺口会计；Berkowitz, Logue and Noser, The Overall Costs of Transaction Execution, Journal of Finance, 1988；Kissell 对执行质量分解的实务框架整理</footer></div><p><a href="/quant/obizhaeva-wang">上一课</a>用线性供给与指数弹性描述限价簿的消耗–恢复，最优常呈期初块、中间连续、期末块；参数是深度密度与弹性，不能把 AC 的 \\(\\eta\\) 改名套用。那是事前控制。缺口是成交后分析：对已完成的母单选定基准，把实现均价、费用、延误与未成交对照过去，按场所、算法、紧急度分层，再喂回路由与日程。TCA 不是盘中决策规则，也不替代事前最优控制。本课写基准如何选、如何拆。若基准可以事后挑选，任何算法都能在某一把尺子上赢。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>交易台每天留下大量子单：时间戳、场所、方向、量、价、费用、取消。没有基准，这些数只是成交记录。有了基准，每笔可以写成相对某个参照价的滑点。问题是参照价有很多个，且彼此不互相蕴含。决策价（经理信号）上的 <a href="/quant/implementation-shortfall">实施缺口</a> 问你有没有买到纸面组合；到达价问执行台接手之后亏了多少；VWAP / TWAP 问你是否贴住窗口均价；收盘价问你相对日终标记。同一笔单可以相对 VWAP 为负、相对到达价为正：市场单边走了，你贴着量加权均价买完，相对决策时刻仍然亏。</p><p>TCA 要解决的不是「选出一个永远正确的基准」，而是：事先声明主尺子与若干副尺子，使算法之间的比较在同一信息集上进行，并把未完成、公司行动、跨日窗口处理成明确规则。若基准可以在事后挑选，任何算法都能在某一把尺子上赢。Kissell 把缺口拆成延误、即时成本、过程中市场运动与机会成本，正是为了让「赢在哪一项」可争论，而不是只报一个净滑点。</p><h3 id="事先基准与条件化" tabindex="-1">事先基准与条件化 <a class="header-anchor" href="#事先基准与条件化" aria-label="Permalink to &quot;事先基准与条件化&quot;">​</a></h3><p>主基准必须在母单下达时就锁定：到达中间价、决策中间价、或预先指定的 TWAP 窗口。副基准可以并行计算，用于诊断，不能用于给算法发奖金后再选。条件化是第二层约束：按市值、波动、参与率、买卖方向、是否含拍卖、是否多日执行分层。无条件平均会把「接了更难的单」的算法判成更差。Keim 与 Madhavan 的机构交易成本研究反复表明，成本随急迫性与公司规模变；TCA 若不分这些轴，比较的是订单流的难度，不是路由的技能。</p><p><span class="marginnote">把「平均滑点为负」写成交易台创造了 alpha，通常是样本里含大量被动成交与价格改善。逆向选择会在随后的实现价差里出现，见 <a href="/quant/effective-realized-spread">有效价差与实现价差</a>。TCA 的窗口若在成交后立即结束，会把做市式的负即时滑点误读成执行优势。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对母单 \\(i\\)，记目标量 \\(Q_i\\)、成交量 \\(q_i\\)、成交均价 \\(\\bar P_i\\)、基准 \\(B_i\\)、结束标记 \\(P_{e,i}\\)、显式费用 \\(F_i\\)。买入的符号约定下，一个最小报告集是</p> \\[\\mathrm{slip}_i = q_i(\\bar P_i-B_i)+ (Q_i-q_i)(P_{e,i}-B_i)+F_i. \\]<p>\\(B_i\\) 取到达中间价时，这就是到达价实施缺口；\\(B_i\\) 取窗口 VWAP 时，未成交项的含义变了——VWAP 本身含你的成交，高参与率下基准被自己污染。报告应同时给出已执行项与未执行项，避免用放弃来「做低」已执行滑点。多日母单要把隔夜跳空单列，否则第一日收盘到第二日开盘的运动会被算进冲击。</p><p>分层统计。对 \\(\\mathrm{slip}_i/Q_i\\) 按场所、订单类型（maker / taker / 暗池）、算法名称、参与率桶做均值与分位数，并报告单数。均值被少数大单主导时，应同时给金额加权与等权。金额加权回答「钱亏在哪」；等权回答「这类单是否系统性地贵」。两者方向相反时，问题往往在尾部大单的保护价或收盘扫档。</p><h3 id="从会计到参数-闭环" tabindex="-1">从会计到参数：闭环 <a class="header-anchor" href="#从会计到参数-闭环" aria-label="Permalink to &quot;从会计到参数：闭环&quot;">​</a></h3><p>TCA 只有连回参数才有工程价值。例子：某场所的 taker 缺口持续高于费用调整后的可见深度所暗示的水平，则 <a href="/quant/smart-order-routing">SOR</a> 应下调该所的立即成交分配；某暗池成交率低于阈值且事后中点向成交方向漂移，则降低暗处比例，把量送回明簿被动。日程层：POV 在高波动桶的未完成率上升，应放宽时间或降低参与率，而不是在窗口末端市价清扫——清扫会在 TCA 的尾部分位数上留下尖刺。</p><p>对照实验比前后比较更干净。同一类母单轮换两条路由规则（A/B），比「本月换了参数、缺口下降」更少被行情污染。无法做随机化时，至少用到达后市场方向做回归：把滑点对同期不交易的对照收益回归，残差才更像执行成本。不做这一步，单边市里的所有主动算法都会一起变差或一起变好。</p><p><span class="marginnote">VWAP 基准在自己参与率高时部分是「跟自己比」。Perold 的纸面组合不依赖事后市场均价；机构若只用 VWAP KPI，SOR 会被训练去贴成交量曲线，而不是缩小决策缺口。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>TCA 能改进执行，是因为它把不可见的摩擦写成可加总、可分层的数字，使参数调整有梯度。价差与费用是相对稳定的一层；冲击随参与率上升；时机风险随窗口拉长；机会成本随未完成与价格漂移上升。分层之后，可以区分「费用表改了」与「路由把量送到了更毒的流里」。后者会同时表现为：即时有效价差尚可、实现价差恶化——成交后中点顺着你的方向走。</p><p>激励是机制的另一半。若交易员的考核只看相对 VWAP，他们会在基准截止前对齐，甚至把难做的剩余量推到「不算进窗口」的区域。若只看实施缺口而不看未完成率，又会激励用放弃来避免实现滑点——放弃只是把成本搬到机会成本项。治理应指定主尺子（通常是到达价或决策价缺口），强制披露未完成率与参与率，并把暗池、拍卖、连续竞价分开，以免一种场所的优势掩盖另一种场所的恶化。</p><p>Berkowitz 等人用 VWAP 度量的是「相对当时市场，你的成交贵不贵」，适合回答经纪商通道质量；Perold 度量的是「相对决策，投资过程丢掉了什么」。TCA 平台常常两种都算。写报告时必须标明：你在评价经纪商、评价算法、还是评价投资经理与交易台的交接。三种对象混在一张表里，数字无法行动。</p><h3 id="配对与篮子的组合缺口" tabindex="-1">配对与篮子的组合缺口 <a class="header-anchor" href="#配对与篮子的组合缺口" aria-label="Permalink to &quot;配对与篮子的组合缺口&quot;">​</a></h3><p>统计套利母单是多腿的。分腿 TCA 可以显示「多头腿跑赢 VWAP、空头腿也还行」，组合却在开仓窗口内把价差打穿——两腿不同步。组合缺口应以信号触发时的价差（或篮子净值）为基准，把随后的腿间滑点算进执行，而不是算进 alpha。这与 <a href="/quant/distance-pairs">距离法配对</a> 或 <a href="/quant/pca-stat-arb">PCA 统计套利</a> 的回测假设直接冲突：纸面假定次日可同时成交；TCA 要报告两腿时间差与单边暴露的分钟数。没有这项，研究里的净边缘含有不可执行的同步性。</p><p><span class="marginnote">公司行动、停牌、涨跌停会使基准价格不可成交。TCA 应把这些母单标成单独一层，而不是让它们的巨大滑点污染普通连续竞价的均值。A 股涨跌停上的「未完成」是制度，不是算法偷懒。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>TCA 是事后，不能在盘中当最优控制用。用上一阶段的平均滑点当下一笔的冲击预测，是粗糙但可用的先验；用它替代状态依赖的深度与毒性，会在体制切换时滞后。数据质量决定一切：时钟同步、成交方向、中间价是否含自身成交、暗池打印延迟，都会改滑点几个基点，而这几个基点往往就是算法之间的全部差别。</p><p>不要用全样本一个数字比较两种 SOR。不要在基准集合里事后挑选「对我们有利的那把尺子」。不要把研究账户的纸面再平衡缺口与交易台的到达价缺口加总成「总 TCA」却不声明决策点。外汇与期货还有点差惯例、展期与结算价规则，股票上的到达中间价不能原样搬过去。</p><p>与事前模型的分工：Almgren–Chriss 一类给出窗口内的目标速率；TCA 检验实现成本是否与校准的冲击函数一致。若事后成本系统性高于模型，应重估冲击，而不是把模型夏普留在研究端、把超支留在交易端。容量结论必须来自按参与率分层的 TCA，而不是来自零冲击回测，见 <a href="/quant/capacity-participation">容量与参与率</a>。</p>',29)),(e(),n(p,null,{default:i(()=>[s(r,{id:"mermaid-83",class:"mermaid",graph:"flowchart%20TD%0A%20%20FILL%5B%22%E5%AD%90%E5%8D%95%E6%88%90%E4%BA%A4%E4%B8%8E%E6%9C%AA%E6%88%90%E4%BA%A4%22%5D%20--%3E%20BENCH%5B%22%E4%BA%8B%E5%85%88%E9%94%81%E5%AE%9A%E7%9A%84%E5%9F%BA%E5%87%86%20B%22%5D%0A%20%20BENCH%20--%3E%20SLIP%5B%22%E6%BB%91%E7%82%B9%3A%20%E5%B7%B2%E6%89%A7%E8%A1%8C%20%2B%20%E6%9C%BA%E4%BC%9A%E6%88%90%E6%9C%AC%20%2B%20%E8%B4%B9%E7%94%A8%22%5D%0A%20%20SLIP%20--%3E%20STRAT%5B%22%E6%8C%89%E5%9C%BA%E6%89%80%20%2F%20%E7%B1%BB%E5%9E%8B%20%2F%20%E5%8F%82%E4%B8%8E%E7%8E%87%E5%88%86%E5%B1%82%22%5D%0A%20%20STRAT%20--%3E%20ALG%5B%22%E5%8F%8D%E9%A6%88%3A%20%E6%97%A5%E7%A8%8B%E4%B8%8E%20SOR%20%E5%8F%82%E6%95%B0%22%5D%0A%20%20STRAT%20--%3E%20GOV%5B%22%E4%B8%BB%20KPI%3A%20%E5%88%B0%E8%BE%BE%E4%BB%B7%E6%88%96%E5%86%B3%E7%AD%96%E4%BB%B7%E7%BC%BA%E5%8F%A3%22%5D%0A%20%20GOV%20--%3E%20VWAP%5B%22%E5%89%AF%E5%B0%BA%3A%20VWAP%20%2F%20TWAP%22%5D%0A%20%20SLIP%20--%3E%20PAIR%5B%22%E5%A4%9A%E8%85%BF%3A%20%E7%BB%84%E5%90%88%E4%BB%B7%E5%B7%AE%E5%9F%BA%E5%87%86%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>TCA 是成交后把实现均价与未完成对照事先基准的会计，用来改路由与日程参数，不是盘中公式。</li><li>主基准须在下达时锁定；实施缺口与 VWAP 回答不同问题，事后挑选基准会使任何算法看起来都赢。</li><li>报告要拆已执行 / 未执行，并按难度轴分层；无条件均值比较的是订单流，不是技能。</li><li>多腿策略必须用组合缺口，分腿跑赢 VWAP 不能证明同步开仓可执行。</li><li>出处：Perold, <em>JPM</em>, 1988；Berkowitz, Logue and Noser, <em>Journal of Finance</em>, 1988；分解框架见 Kissell 的执行质量论述。</li></ul>',2))])}const C=o(B,[["render",d]]);export{m as __pageData,C as default};
